/**
 * Verify Pending Predictions — HISTORICAL-AWARE
 * =============================================
 * Evaluates each PENDING prediction against prices in the 30-day window
 * AFTER the prediction date (not just current_price). This properly
 * closes historical predictions generated by backfill_to_predictions.py.
 *
 * Algorithm:
 *   For each PENDING prediction with prediction_date = T:
 *   - Read prices from price_history.db for T+1 ... T+30 days
 *   - BUY: hit_target if any high >= target_price; hit_stop if any low <= stop_loss
 *   - SELL: hit_target if any low <= target_price; hit_stop if any high >= stop_loss
 *   - First hit wins (earliest day where target or stop triggered)
 *   - If no hit in 30 days → EXPIRED (exit = close on T+30 or last available)
 *   - actual_return = direction-aware: BUY (exit-entry)/entry*100, SELL (entry-exit)/entry*100
 *
 * Falls back to stocks.db.current_price for recent predictions (last 7 days)
 * where price_history may not have post-prediction data yet.
 *
 * PURE SQLITE — no Python dependency.
 *
 * Request:  POST /api/predictions/honest-tracking/verify-pending
 *           Body: { limit?: number, params?: MaestroParams }
 *
 * Response: { success, results: { checked, target_hits, stopped, expired,
 *           still_pending, errors }, closed: [...], closed_count, price_sources }
 */

import { NextRequest, NextResponse } from 'next/server';
import Database from 'better-sqlite3';
import path from 'path';
import { DEFAULT_PARAMS, type MaestroParams } from '@/lib/honest-tracking/maestro';

export const dynamic = 'force-dynamic';

const EVAL_WINDOW_DAYS = 30; // predictions evaluated against prices in T+1..T+30
const RECENT_FALLBACK_DAYS = 7; // use current_price for predictions < 7 days old

function openDb(dbPath: string, readonly: boolean): Database.Database {
  try {
    return new Database(dbPath, { readonly, timeout: 5000, fileMustExist: true });
  } catch {
    return new Database(`file:${dbPath}?immutable=1`, { readonly: true, timeout: 5000 });
  }
}

interface PriceRow {
  date: string;
  high_price: number | null;
  low_price: number | null;
  close_price: number | null;
}

// ============================================================================
// TECHNICAL EXIT STRATEGY
// ============================================================================
// The user's insight: we don't need to wait for the exact target price.
// We can sell BEFORE the target as long as there's profit, based on
// technical analysis signals. This is how real traders operate.
//
// Exit signals (checked each day after entry):
//   1. STOP LOSS hit → exit at stop (loss)
//   2. TARGET hit → exit at target (full win)
//   3. PROFIT-TAKING signals (only when in profit):
//      a. RSI > 75 (overbought) → sell at close (take profit)
//      b. Price closed below MA20 (trend reversal) → sell at close
//      c. Price dropped X% from peak (trailing stop) → sell at close
//   4. TIME EXIT: if 30 days pass with no signal → exit at last close
//
// This means a prediction can WIN even without hitting the exact target,
// as long as a profit-taking signal appeared while the position was profitable.

interface TechIndicators {
  rsi: number | null;
  ma20: number | null;
  prevClose: number | null;
}

/** Compute RSI from a window of closes. */
function computeRsiAt(closes: number[], period: number = 14): number | null {
  if (closes.length < period + 1) return null;
  let gains = 0, losses = 0;
  for (let i = closes.length - period; i < closes.length; i++) {
    const change = closes[i] - closes[i - 1];
    if (change > 0) gains += change;
    else losses += Math.abs(change);
  }
  const avgGain = gains / period;
  const avgLoss = losses / period;
  if (avgLoss === 0) return 100;
  const rs = avgGain / avgLoss;
  return Math.round((100 - (100 / (1 + rs))) * 100) / 100;
}

/** Compute SMA at a point. */
function computeMaAt(closes: number[], period: number): number | null {
  if (closes.length < period) return null;
  const slice = closes.slice(-period);
  return Math.round((slice.reduce((a, b) => a + b, 0) / period) * 100) / 100;
}

/**
 * Smart exit evaluator — walks day by day, returns the exit decision.
 * Implements the user's strategy: sell before target if technical signals say so.
 *
 * SPLIT DETECTION: If a stock undergoes a split/denomination change, prices
 * jump discontinuously (e.g., ARAB went from 130 → 0.20 overnight). We detect
 * this by checking if any price in the window is >5x or <1/5x the entry_price.
 * When detected, we SKIP evaluation (return SPLIT_DETECTED) to avoid
 * impossible returns like +70025%.
 */
function evaluateExit(
  rows: PriceRow[],
  entry: number,
  target: number,
  stop: number,
  isBuy: boolean,
  predDateStr: string,
  params: MaestroParams
): {
  outcome: 'TARGET_HIT' | 'STOPPED' | 'PROFIT_TAKEN' | 'EXPIRED' | 'SPLIT_DETECTED';
  exitDate: string;
  exitPrice: number;
  holdingDays: number;
  highestPrice: number;
  exitReason: string;
} {
  // SPLIT DETECTION — check if any price in the window is on a different scale
  // than the entry price. If entry=0.20 but window prices are ~130, that's a split.
  const SPLIT_RATIO = 5; // if prices differ by >5x, it's a split
  for (const r of rows) {
    const high = Number(r.high_price || 0);
    const low = Number(r.low_price || 0);
    const close = Number(r.close_price || 0);
    if (high <= 0 || low <= 0 || close <= 0) continue;
    if (high > entry * SPLIT_RATIO || low < entry / SPLIT_RATIO ||
        close > entry * SPLIT_RATIO || close < entry / SPLIT_RATIO) {
      // Split detected — can't evaluate reliably
      return {
        outcome: 'SPLIT_DETECTED',
        exitDate: r.date,
        exitPrice: entry, // keep entry as exit (no change)
        holdingDays: 0,
        highestPrice: entry,
        exitReason: `split_detected_entry=${entry}_window_high=${high}_low=${low}`,
      };
    }
  }

  const closes: number[] = [];
  let peakPrice = entry; // track highest (for BUY) or lowest (for SELL)
  const TRAILING_STOP_PCT = params.trailingStopPct; // exit if price drops X% from peak
  const MIN_PROFIT_PCT = params.minProfitPct; // only take profit signals when >= Y% in profit

  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    const high = Number(r.high_price || 0);
    const low = Number(r.low_price || 0);
    const close = Number(r.close_price || 0);
    if (high <= 0 || low <= 0 || close <= 0) continue;

    closes.push(close);
    const holdingDays = Math.max(0, Math.floor(
      (parseDate(r.date).getTime() - parseDate(predDateStr).getTime()) / 86_400_000
    ));

    // Update peak price
    if (isBuy) {
      if (high > peakPrice) peakPrice = high;
    } else {
      if (low < peakPrice) peakPrice = low;
    }

    // 1. STOP LOSS check (highest priority)
    if (isBuy && low <= stop) {
      return {
        outcome: 'STOPPED', exitDate: r.date, exitPrice: stop,
        holdingDays, highestPrice: peakPrice, exitReason: 'stop_loss_hit',
      };
    }
    if (!isBuy && high >= stop) {
      return {
        outcome: 'STOPPED', exitDate: r.date, exitPrice: stop,
        holdingDays, highestPrice: peakPrice, exitReason: 'stop_loss_hit',
      };
    }

    // 2. TARGET check (full win)
    if (isBuy && high >= target) {
      return {
        outcome: 'TARGET_HIT', exitDate: r.date, exitPrice: target,
        holdingDays, highestPrice: peakPrice, exitReason: 'target_hit',
      };
    }
    if (!isBuy && low <= target) {
      return {
        outcome: 'TARGET_HIT', exitDate: r.date, exitPrice: target,
        holdingDays, highestPrice: peakPrice, exitReason: 'target_hit',
      };
    }

    // 3. PROFIT-TAKING signals (only when in profit)
    const currentReturn = isBuy
      ? ((close - entry) / entry) * 100
      : ((entry - close) / entry) * 100;

    if (currentReturn >= params.minProfitPct * 100) {
      // 3a. RSI overbought (BUY positions only — take profit when overbought)
      const rsi = computeRsiAt(closes, params.rsiPeriod);
      if (isBuy && rsi !== null && rsi >= params.rsiOverbought) {
        return {
          outcome: 'PROFIT_TAKEN', exitDate: r.date, exitPrice: close,
          holdingDays, highestPrice: peakPrice,
          exitReason: `rsi_overbought_${rsi}`,
        };
      }
      // For SELL positions: RSI oversold = profit take
      if (!isBuy && rsi !== null && rsi <= params.rsiOversold) {
        return {
          outcome: 'PROFIT_TAKEN', exitDate: r.date, exitPrice: close,
          holdingDays, highestPrice: peakPrice,
          exitReason: `rsi_oversold_${rsi}`,
        };
      }

      // 3b. Trend reversal: price closed below MA20 (for BUY) or above MA20 (for SELL)
      const ma20 = computeMaAt(closes, params.swingLookback);
      if (ma20 !== null) {
        if (isBuy && close < ma20 && currentReturn >= MIN_PROFIT_PCT) {
          return {
            outcome: 'PROFIT_TAKEN', exitDate: r.date, exitPrice: close,
            holdingDays, highestPrice: peakPrice,
            exitReason: `ma20_reversal_close_below_${ma20}`,
          };
        }
        if (!isBuy && close > ma20 && currentReturn >= MIN_PROFIT_PCT) {
          return {
            outcome: 'PROFIT_TAKEN', exitDate: r.date, exitPrice: close,
            holdingDays, highestPrice: peakPrice,
            exitReason: `ma20_reversal_close_above_${ma20}`,
          };
        }
      }

      // 3c. Trailing stop: price dropped X% from peak (BUY) or rose X% from trough (SELL)
      const dropFromPeak = isBuy
        ? ((peakPrice - close) / peakPrice) * 100
        : ((close - peakPrice) / peakPrice) * 100;
      if (dropFromPeak >= params.trailingStopPct * 100 && currentReturn >= params.minProfitPct * 100) {
        return {
          outcome: 'PROFIT_TAKEN', exitDate: r.date, exitPrice: close,
          holdingDays, highestPrice: peakPrice,
          exitReason: `trailing_stop_${Math.round(dropFromPeak)}pct_from_peak`,
        };
      }
    }
  }

  // 4. TIME EXIT — no signal in the window, exit at last close
  const lastRow = rows[rows.length - 1];
  const lastClose = Number(lastRow.close_price || entry);
  return {
    outcome: 'EXPIRED',
    exitDate: lastRow.date,
    exitPrice: lastClose,
    holdingDays: EVAL_WINDOW_DAYS,
    highestPrice: peakPrice,
    exitReason: 'time_exit_30d',
  };
}

interface Prediction {
  id: number;
  ticker: string;
  signal_type: string;
  signal: string;
  prediction_date: string;
  entry_price: number;
  target_price: number | null;
  stop_loss: number | null;
}

interface ClosedRecord {
  id: number;
  ticker: string;
  signal_type: string;
  outcome: 'TARGET_HIT' | 'STOPPED' | 'EXPIRED' | 'PROFIT_TAKEN';
  entry_price: number;
  exit_price: number;
  actual_return: number;
  holding_days: number;
  exit_reason?: string;
}

interface VerifyResults {
  checked: number;
  target_hits: number;
  stopped: number;
  expired: number;
  still_pending: number;
  errors: number;
  profit_taken?: number; // NEW: technical exit with profit (sell before target)
}

/** Parse prediction_date (may be "YYYY-MM-DD HH:MM:SS" or "YYYY-MM-DD") to a Date. */
function parseDate(s: string): Date {
  const d = new Date(s.replace(' ', 'T'));
  return isNaN(d.getTime()) ? new Date(s) : d;
}

/** Add days to a Date, return YYYY-MM-DD string. */
function addDays(d: Date, days: number): string {
  const r = new Date(d.getTime() + days * 86_400_000);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${r.getFullYear()}-${pad(r.getMonth() + 1)}-${pad(r.getDate())}`;
}

async function handle(req: NextRequest) {
  // HONEST-V2: bumped from 5000 → 10000 so the user can close ALL pending
  // trades aggressively with a single click (see "verify-pending limit"
  // requirement in the task brief).
  let limit = 5000;
  const params: MaestroParams = { ...DEFAULT_PARAMS };
  try {
    if (req.method === 'POST' || req.method === 'PUT') {
      const text = await req.text();
      if (text) {
        const body = JSON.parse(text);
        if (typeof body.limit === 'number' && body.limit > 0) {
          limit = Math.min(Math.floor(body.limit), 10000);
        }
        if (body.params && typeof body.params === 'object') {
          const tp = body.params;
          if (typeof tp.atrPeriod === 'number') params.atrPeriod = Math.max(2, Math.min(100, tp.atrPeriod));
          if (typeof tp.swingLookback === 'number') params.swingLookback = Math.max(5, Math.min(100, tp.swingLookback));
          if (typeof tp.rsiOverbought === 'number') params.rsiOverbought = Math.max(50, Math.min(100, tp.rsiOverbought));
          if (typeof tp.rsiOversold === 'number') params.rsiOversold = Math.max(0, Math.min(50, tp.rsiOversold));
          if (typeof tp.rsiPeriod === 'number') params.rsiPeriod = Math.max(2, Math.min(30, tp.rsiPeriod));
          if (typeof tp.minRiskReward === 'number') params.minRiskReward = Math.max(0.5, Math.min(10, tp.minRiskReward));
          if (typeof tp.exitSignalThreshold === 'number') params.exitSignalThreshold = Math.max(0, Math.min(100, tp.exitSignalThreshold));
        }
      }
    }
  } catch {
    /* use defaults */
  }

  const cwd = process.cwd();
  const predDbPath = path.join(cwd, 'db', 'predictions.db');
  const priceDbPath = path.join(cwd, 'db', 'price_history.db');
  const stocksDbPath = path.join(cwd, 'db', 'stocks.db');

  let pdb: Database.Database;
  let priceDb: Database.Database | null = null;
  let stocksDb: Database.Database | null = null;

  try {
    pdb = openDb(predDbPath, false);
  } catch (e) {
    return NextResponse.json(
      { success: false, error: `Cannot open predictions.db: ${e instanceof Error ? e.message : 'unknown'}` },
      { status: 500 }
    );
  }

  try {
    priceDb = openDb(priceDbPath, true);
  } catch {
    /* price_history.db optional */
  }

  try {
    stocksDb = openDb(stocksDbPath, true);
  } catch {
    /* stocks.db optional */
  }

  const results: VerifyResults = {
    checked: 0,
    target_hits: 0,
    stopped: 0,
    expired: 0,
    still_pending: 0,
    errors: 0,
    profit_taken: 0, // NEW: technical exit with profit
  };
  const closed: ClosedRecord[] = [];
  const priceSources: Record<string, number> = {
    price_history: 0,
    stocks_current: 0,
    unresolved: 0,
  };

  try {
    // Fetch PENDING predictions — SCHEMA-MISMATCH-FIX: استثني التوقعات المقفولة
    // بـ trading pipeline (status='CLOSED' / exit_type) حتى لو outcome_date NULL.
    // قبل كده كان بـ يعيد معالجة صفقات مقفولة → تـ double-count أو تـ overwrite.
    const preds = pdb.prepare(`
      SELECT id, ticker, signal_type, signal, prediction_date,
             entry_price, target_price, stop_loss
      FROM predictions
      WHERE outcome_date IS NULL
        AND UPPER(TRIM(COALESCE(status, ''))) != 'CLOSED'
        AND exit_type IS NULL
      ORDER BY prediction_date ASC
      LIMIT ?
    `).bind(limit).all() as Prediction[];

    // Pre-fetch current_price map from stocks.db (for recent fallback)
    const currentPriceMap = new Map<string, { price: number; asOf: string }>();
    if (stocksDb) {
      try {
        const rows = stocksDb.prepare(
          `SELECT ticker, current_price, last_update FROM stocks WHERE current_price > 0`
        ).all() as Array<{ ticker: string; current_price: number; last_update: string }>;
        for (const r of rows) {
          currentPriceMap.set(r.ticker, {
            price: Number(r.current_price),
            asOf: r.last_update || new Date().toISOString(),
          });
        }
      } catch {
        /* table missing — skip */
      }
    }

    // Prepare update statement
    // HONEST-V2: also persist exit_reason so the detail panel can show why
    // the trade was closed (target_hit / stop_loss / rsi_overbought / etc.).
    // The exit_reason column is added by ensureSchema() in maestro.ts; if the
    // column doesn't exist yet on an old DB, we add it here on the fly.
    try {
      const cols = pdb.prepare('PRAGMA table_info(predictions)').all() as Array<{ name: string }>;
      if (cols.length > 0 && !cols.some(c => c.name === 'exit_reason')) {
        pdb.exec('ALTER TABLE predictions ADD COLUMN exit_reason TEXT');
      }
    } catch { /* ignore */ }
    const updateStmt = pdb.prepare(`
      UPDATE predictions
      SET outcome_date = ?,
          exit_price = ?,
          actual_return = ?,
          hit_target = ?,
          hit_stop = ?,
          is_correct = ?,
          holding_days = ?,
          highest_price_reached = ?,
          exit_reason = ?
      WHERE id = ?
    `);

    const tx = pdb.transaction(() => {
      for (const p of preds) {
        results.checked++;
        try {
          if (!p.target_price || !p.stop_loss || !p.entry_price || p.entry_price <= 0) {
            results.errors++;
            continue;
          }

          const predDate = parseDate(p.prediction_date);
          const predDateStr = p.prediction_date.slice(0, 10); // YYYY-MM-DD
          const windowEnd = addDays(predDate, EVAL_WINDOW_DAYS);
          const isRecent = (Date.now() - predDate.getTime()) < RECENT_FALLBACK_DAYS * 86_400_000;

          const target = Number(p.target_price);
          const stop = Number(p.stop_loss);
          const entry = Number(p.entry_price);
          const isBuy = (p.signal_type || p.signal || '').toUpperCase() === 'BUY';
          const isSell = (p.signal_type || p.signal || '').toUpperCase() === 'SELL';

          if (!isBuy && !isSell) {
            // HOLD or unknown — skip
            results.still_pending++;
            continue;
          }

          // 1. Try price_history.db for the 30-day window after prediction
          //    AXIS-8: أصلحنا ترتيب المصادر + فلتر NULL close_price.
          //    الأولوية الآن تطابق TV-PRIMARY:
          //      (a) yahoo_clean + tradingview_live (التاريخ الأساسي — أكبر تغطية)
          //      (b) egksco (intraday cleanest)
          //      (c) egx_investment_migration (fallback قديم مُطبّع)
          //      (d) stock_daily_prices (آخر ملجأ — بيانات حديثة)
          //    كل استعلام بـ يفلتر NULL/zero في close/high/low عشان نمنع
          //    الصفوف الملوّثة (زي low=15.0 لـ GETO entry=297) من تمرير بيانات فاسدة.
          let resolved = false;
          if (priceDb) {
            let rows: PriceRow[] = [];
            // AXIS-8: المصدر الأساسي — yahoo_clean + tradingview_live (أكبر تغطية)
            try {
              rows = priceDb.prepare(`
                SELECT date, high_price, low_price, close_price
                FROM price_history
                WHERE ticker = ? AND date > ? AND date <= ?
                  AND source IN ('yahoo_clean', 'tradingview_live', 'yahoo_safetynet')
                  AND close_price IS NOT NULL AND close_price > 0
                  AND high_price IS NOT NULL AND high_price > 0
                  AND low_price IS NOT NULL AND low_price > 0
                ORDER BY date ASC
              `).bind(p.ticker, predDateStr, windowEnd).all() as PriceRow[];
            } catch {
              /* price_history query failed — fall through */
            }

            // Fallback 1: egksco (intraday cleanest)
            if (rows.length === 0) {
              try {
                rows = priceDb.prepare(`
                  SELECT date, high_price, low_price, close_price
                  FROM price_history
                  WHERE ticker = ? AND date > ? AND date <= ? AND source = 'egksco'
                    AND close_price IS NOT NULL AND close_price > 0
                    AND high_price IS NOT NULL AND high_price > 0
                    AND low_price IS NOT NULL AND low_price > 0
                  ORDER BY date ASC
                `).bind(p.ticker, predDateStr, windowEnd).all() as PriceRow[];
              } catch {
                /* ignore */
              }
            }

            // Fallback 2: egx_investment_migration (more data, covers all markets)
            if (rows.length === 0) {
              try {
                rows = priceDb.prepare(`
                  SELECT date, high_price, low_price, close_price
                  FROM price_history
                  WHERE ticker = ? AND date > ? AND date <= ? AND source = 'egx_investment_migration'
                    AND close_price IS NOT NULL AND close_price > 0
                    AND high_price IS NOT NULL AND high_price > 0
                    AND low_price IS NOT NULL AND low_price > 0
                  ORDER BY date ASC
                `).bind(p.ticker, predDateStr, windowEnd).all() as PriceRow[];
              } catch {
                /* ignore */
              }
            }

            // Fallback 3: stock_daily_prices in stocks.db (recent data)
            let effectiveRows = rows;
            if (rows.length === 0 && stocksDb) {
              try {
                const sdpRows = stocksDb.prepare(`
                  SELECT price_date as date, high, low, close as close_price
                  FROM stock_daily_prices
                  WHERE ticker = ? AND price_date > ? AND price_date <= ?
                    AND close IS NOT NULL AND close > 0
                    AND high IS NOT NULL AND high > 0
                    AND low IS NOT NULL AND low > 0
                  ORDER BY price_date ASC
                `).bind(p.ticker, predDateStr, windowEnd).all() as PriceRow[];
                effectiveRows = sdpRows as any;
              } catch {
                /* table missing */
              }
            }

            if (effectiveRows.length > 0) {
              // VALIDATION: Check if entry_price matches the actual market price.
              // If entry is off by >3x from the first window price, the entry_price
              // itself is corrupted (from egx_investment_migration). Skip evaluation.
              const firstClose = Number(effectiveRows[0].close_price || 0);
              if (firstClose > 0 && entry > 0) {
                const ratio = Math.max(entry, firstClose) / Math.min(entry, firstClose);
                if (ratio > 3) {
                  // entry_price is on a different scale — can't evaluate
                  priceSources.unresolved++;
                  results.still_pending++;
                  results.errors++;
                  resolved = false;
                  // Skip to next prediction
                  continue;
                }
              }

              // AXIS-8: DataClean guard على مستوى الصف — فلتر الأسعار المستحيلة
              // اللي ممكن تمر من SQL NULL filter (قيم مش NULL بس فاسدة، زي
              // close=15.0 لسهم entry=297 بسبب split/ticker confusion).
              // نحذف أي صف بـ close خارج [entry×0.2, entry×5.0] أو high/low
              // خارج النطاق. ده يطابق سلوك Python daily_closer DataClean guard.
              if (entry > 0) {
                const _cleanRows = effectiveRows.filter(r => {
                  const c = Number(r.close_price || 0);
                  const h = Number(r.high_price || 0);
                  const l = Number(r.low_price || 0);
                  if (c <= 0 || c < entry * 0.2 || c > entry * 5.0) return false;
                  if (h > 0 && (h < entry * 0.2 || h > entry * 5.0)) return false;
                  if (l > 0 && (l < entry * 0.2 || l > entry * 5.0)) return false;
                  if (h > 0 && l > 0 && h < l) return false; // invalid OHLC
                  return true;
                });
                if (_cleanRows.length > 0) {
                  effectiveRows = _cleanRows;
                } else {
                  // كل الصفوف فاسدة — اعتبره غير قابل للتحقق
                  priceSources.unresolved++;
                  results.still_pending++;
                  resolved = false;
                  continue;
                }
              }

              priceSources.price_history++;

              // Use the SMART exit evaluator (technical-analysis-based)
              const exit = evaluateExit(effectiveRows, entry, target, stop, isBuy, predDateStr, params);

              if (exit.outcome === 'SPLIT_DETECTED') {
                priceSources.unresolved++;
                results.still_pending++;
                resolved = false;
              } else {
                resolved = true;
                const actualReturn = isBuy
                  ? ((exit.exitPrice - entry) / entry) * 100
                  : ((entry - exit.exitPrice) / entry) * 100;

                // FINAL SANITY CHECK: if return is impossible (>100% or <-90%), skip
                // A 100% return in 30 days is already exceptional — anything above
                // indicates a data error (wrong entry_price, stock split, etc.)
                if (actualReturn > 100 || actualReturn < -90) {
                  priceSources.unresolved++;
                  results.still_pending++;
                  results.errors++;
                  resolved = false;
                  continue;
                }

                updateStmt.run(
                  exit.exitDate + ' 15:00:00',
                  exit.exitPrice,
                  Math.round(actualReturn * 100) / 100,
                  exit.outcome === 'TARGET_HIT' ? 1 : 0,
                  exit.outcome === 'STOPPED' ? 1 : 0,
                  actualReturn > 0 ? 1 : 0,
                  exit.holdingDays,
                  exit.highestPrice,
                  exit.exitReason,
                  p.id
                );

                if (exit.outcome === 'TARGET_HIT') results.target_hits++;
                else if (exit.outcome === 'STOPPED') results.stopped++;
                else if (exit.outcome === 'PROFIT_TAKEN') {
                  results.profit_taken = (results.profit_taken || 0) + 1;
                } else results.expired++;

                closed.push({
                  id: p.id, ticker: p.ticker, signal_type: p.signal_type,
                  outcome: exit.outcome,
                  entry_price: entry, exit_price: exit.exitPrice,
                  actual_return: Math.round(actualReturn * 100) / 100,
                  holding_days: exit.holdingDays,
                  exit_reason: exit.exitReason,
                });
              }
            }
          }

          // 2. Fallback for recent predictions: use current_price from stocks.db
          if (!resolved && isRecent && currentPriceMap.has(p.ticker)) {
            const cur = currentPriceMap.get(p.ticker)!;
            priceSources.stocks_current++;
            resolved = true;

            const current = cur.price;
            let outcome: 'TARGET_HIT' | 'STOPPED' | null = null;
            if (isBuy) {
              if (current >= target) outcome = 'TARGET_HIT';
              else if (current <= stop) outcome = 'STOPPED';
            } else {
              if (current <= target) outcome = 'TARGET_HIT';
              else if (current >= stop) outcome = 'STOPPED';
            }

            if (outcome) {
              const exitPrice = outcome === 'TARGET_HIT' ? target : stop;
              const actualReturn = isBuy
                ? ((exitPrice - entry) / entry) * 100
                : ((entry - exitPrice) / entry) * 100;
              const holding = Math.max(0, Math.floor(
                (Date.now() - predDate.getTime()) / 86_400_000
              ));

              updateStmt.run(
                cur.asOf,
                exitPrice,
                Math.round(actualReturn * 100) / 100,
                outcome === 'TARGET_HIT' ? 1 : 0,
                outcome === 'STOPPED' ? 1 : 0,
                actualReturn > 0 ? 1 : 0,
                holding,
                current,
                outcome === 'TARGET_HIT' ? 'target_hit_current_price' : 'stop_hit_current_price',
                p.id
              );

              if (outcome === 'TARGET_HIT') results.target_hits++;
              else results.stopped++;

              closed.push({
                id: p.id, ticker: p.ticker, signal_type: p.signal_type,
                outcome, entry_price: entry, exit_price: exitPrice,
                actual_return: Math.round(actualReturn * 100) / 100,
                holding_days: holding,
              });
            } else {
              // Still pending (current price between stop and target)
              results.still_pending++;
            }
          }

          if (!resolved) {
            // No price data available — still pending
            priceSources.unresolved++;
            results.still_pending++;
          }
        } catch (e) {
          results.errors++;
        }
      }
    });

    tx();

    return NextResponse.json({
      success: true,
      results,
      closed: closed.slice(0, 50), // first 50 for display
      closed_count: closed.length,
      price_sources: priceSources,
    });
  } catch (e) {
    return NextResponse.json(
      { success: false, error: e instanceof Error ? e.message : 'Unknown error' },
      { status: 500 }
    );
  } finally {
    pdb.close();
    if (priceDb) priceDb.close();
    if (stocksDb) stocksDb.close();
  }
}

export async function POST(req: NextRequest) {
  return handle(req);
}

export async function GET(req: NextRequest) {
  return handle(req);
}
